<?php namespace PlayBrand\Performance; if(!defined('ABSPATH'))exit; final class Admin {public static function init():void{add_action('admin_menu',[self::class,'menu']);add_action('admin_init',[self::class,'settings']);} public static function menu():void{add_management_page('PlayBrand Performance','PlayBrand Performance','manage_options','pbpf',[self::class,'page']);} public static function settings():void{register_setting('pbpf','pbpf_options',['sanitize_callback'=>function($v){return ['enabled'=>empty($v['enabled'])?0:1,'dry_run'=>empty($v['dry_run'])?0:1,'cleanup'=>empty($v['cleanup'])?0:1,'media'=>empty($v['media'])?0:1,'fonts'=>empty($v['fonts'])?0:1,'third_party'=>empty($v['third_party'])?0:1,'denylist'=>sanitize_textarea_field($v['denylist']??'')];}]);} public static function page():void{$o=get_option(PBPF_OPTION,[]);echo '<div class="wrap"><h1>PlayBrand Performance</h1><form method="post" action="options.php">';settings_fields('pbpf'); foreach(['enabled'=>'Ativo','dry_run'=>'Dry-run','cleanup'=>'Limpeza segura','media'=>'Mídia','fonts'=>'Fontes','third_party'=>'Terceiros'] as $k=>$l)printf('<label><input type="checkbox" name="pbpf_options[%s]" value="1" %s> %s</label><br>',esc_attr($k),checked(!empty($o[$k]),true,false),esc_html($l));echo '<p>Handles denylist (um por linha):<br><textarea name="pbpf_options[denylist]" rows="4" cols="60">'.esc_textarea($o['denylist']??'').'</textarea></p>';submit_button();echo '</form><h2>Diagnóstico</h2><pre>'.esc_html(print_r(Diagnostics::report(),true)).'</pre></div>';}}
